-- Heart Gold Inspired Into v1.0.0
-- Standalone HeartGold-inspired opening/title experience for Pokémon Gold Recomp.
-- This mod intentionally does NOT patch the in-game Heart Gold Inspired Into.
--
-- It replaces only:
--   * GoldSilverIntro
--   * TitleState
--   * MainMenu presentation
--
-- It has no dependency on Heart Gold Inspired Into.

return function(mod)
  local function introLog(level,msg)
    if mod and mod.log then pcall(function() mod.log(level,msg) end) end
  end

  -- Standalone font support.
  -- This helper existed in CROSSS UI but was not carried over when the intro
  -- was separated into its own mod. hg20Text() depends on it.
  local EngineFont=nil
  pcall(function() EngineFont=require("src.render.Font") end)
  local introFonts={}

  local function font(size)
    size=math.max(5,math.floor((size or 12)+0.5))
    if introFonts[size] then return introFonts[size] end

    local f=nil
    if EngineFont and EngineFont.PLAINPIXEL then
      local ok,created=pcall(
        love.graphics.newFont,
        EngineFont.PLAINPIXEL,
        size,
        "normal"
      )
      if ok then f=created end
    end

    if not f then
      local ok,created=pcall(love.graphics.newFont,size)
      if ok then f=created end
    end

    f=f or love.graphics.getFont()
    if f and f.setFilter then
      pcall(f.setFilter,f,"nearest","nearest")
    end
    introFonts[size]=f
    return f
  end

  -- HeartGold Pokédex sprite set (National Dex 001-251)
  --
  -- Source: the pokeheartgold source tree supplied by the user.
  -- Large art uses the first 80x80 frame from each HG front sprite.
  -- List art uses the first 32x32 frame from each HG party icon.
  ---------------------------------------------------------------------------
  local HG_FRONT_ATLAS_B64 = [[]]
  local HG_ICON_ATLAS_B64 = [[]]

  local hgFrontAtlas = false
  local hgIconAtlas = false
  local hgFrontQuads = {}
  local hgIconQuads = {}

  local function loadHgDexAtlas(which)
    local isFront = which == "front"
    local cached = isFront and hgFrontAtlas or hgIconAtlas
    if cached ~= false then return cached end

    local payload = isFront and HG_FRONT_ATLAS_B64 or HG_ICON_ATLAS_B64
    local filename = isFront and "crosss_hg_pokedex_front.png"
      or "crosss_hg_pokedex_icons.png"

    local ok,img = pcall(function()
      local bytes = love.data.decode("string","base64",payload)
      local fd = love.filesystem.newFileData(bytes,filename)
      return love.graphics.newImage(fd)
    end)
    if not ok or not img then
      if isFront then hgFrontAtlas=nil else hgIconAtlas=nil end
      return nil
    end
    if img.setFilter then pcall(img.setFilter,img,"nearest","nearest") end
    if isFront then hgFrontAtlas=img else hgIconAtlas=img end
    return img
  end

  local function hgDexQuad(dexNo,which)
    dexNo=math.floor(tonumber(dexNo) or 0)
    if dexNo<1 or dexNo>251 then return nil,nil end

    local isFront=which=="front"
    local cache=isFront and hgFrontQuads or hgIconQuads
    if cache[dexNo] then return loadHgDexAtlas(which),cache[dexNo] end

    local img=loadHgDexAtlas(which)
    if not img then return nil,nil end
    local cell=isFront and 80 or 32
    local atlasW,atlasH=img:getDimensions()
    local idx=dexNo-1
    local col=idx%16
    local row=math.floor(idx/16)
    local q=love.graphics.newQuad(col*cell,row*cell,cell,cell,atlasW,atlasH)
    cache[dexNo]=q
    return img,q
  end

  local function drawHgDexSprite(dexNo,which,x,y,w,h)
    local img,q=hgDexQuad(dexNo,which)
    if not img or not q then return false end
    local cell=which=="front" and 80 or 32
    local scale=math.min(w/cell,h/cell)
    local dx=x+(w-cell*scale)*0.5
    local dy=y+(h-cell*scale)*0.5
    love.graphics.setColor(1,1,1,1)
    love.graphics.draw(img,q,math.floor(dx+0.5),math.floor(dy+0.5),0,scale,scale)
    love.graphics.setColor(1,1,1,1)
    return true
  end


  -- Embedded HeartGold intro music.
  -- Stored on _G rather than as a local to avoid the Lua 200-local limit.
  _G.CROSSS_HG_INTRO_AUDIO_B64=[[]]

  -- HEARTGOLD ORIGINAL 2D INTRO ---------------------------------------------
  -- Original cinematic built for this mod. It is inspired by the pacing and
  -- Game Boy-style presentation of HeartGold fan openings, but every scene,
  -- camera move and transition below is newly composed. No DX theme is used.
