  local hg20Cache={}
  local function hg20Image(key,data,name)
    if hg20Cache[key]~=nil then return hg20Cache[key] or nil end
    local ok,img=pcall(function()
      local bytes=love.data.decode("string","base64",data)
      local fd=love.filesystem.newFileData(bytes,name)
      local out=love.graphics.newImage(fd)
      if out.setFilter then out:setFilter("nearest","nearest") end
      return out
    end)
    hg20Cache[key]=ok and img or false
    return ok and img or nil
  end
  local function hg20Logo() return hg20Image("logo",HG20_LOGO,"hg20_logo.png") end
  local function hg20GF() return hg20Image("gf",HG20_GF,"hg20_gf.png") end
  local function hg20Ethan() return hg20Image("ethan",HG20_ETHAN,"hg20_ethan.png") end
  local function hg20Lyra() return hg20Image("lyra",HG20_LYRA,"hg20_lyra.png") end
  local function hg20Silver() return hg20Image("silver",HG20_SILVER,"hg20_silver.png") end

  local function hg21NewBark() return hg20Image("hg21_newbark",HG21_NEWBARK,"hg21_newbark.png") end
  local function hg21Goldenrod() return hg20Image("hg21_goldenrod",HG21_GOLDENROD,"hg21_goldenrod.png") end
  local function hg21Ecruteak() return hg20Image("hg21_ecruteak",HG21_ECRUTEAK,"hg21_ecruteak.png") end
  local function hg21Bell() return hg20Image("hg21_bell",HG21_BELL,"hg21_bell.png") end
  local function hg21SilverOpen() return hg20Image("hg21_silver_open",HG21_SILVER_OPEN,"hg21_silver_open.png") end
  local function hg21SilverFull() return hg20Image("hg21_silver_full",HG21_SILVER_FULL,"hg21_silver_full.png") end
