  local function hg214EthanFrame(n)
    local p={HG214_ETHAN_NORTH_1,HG214_ETHAN_NORTH_2,HG214_ETHAN_NORTH_3}
    n=((n-1)%3)+1
    return hg20Image("hg214_ethan_"..n,p[n],"hg214_ethan_"..n..".png")
  end

  local function hg215BellBg()
    return hg20Image("hg215_bell_bg",HG215_BELL_BG,"hg215_bell_bg.png")
  end

  local function hg29EaseOutCubic(t)
    t=math.max(0,math.min(1,t or 0))
    return 1-((1-t)*(1-t)*(1-t))
  end



  local function hg21PanCover(img,x,y,w,h,progress,zoom,panX,panY,alpha)
    if not img then return end
    local iw,ih=img:getDimensions()
    local base=math.max(w/iw,h/ih)
    local sc=base*(zoom or 1)
    local dw,dh=iw*sc,ih*sc
    local px=x+(w-dw)/2+(panX or 0)*(progress or 0)
    local py=y+(h-dh)/2+(panY or 0)*(progress or 0)
    love.graphics.setColor(1,1,1,alpha or 1)
    love.graphics.draw(img,px,py,0,sc,sc)
  end
  local function hg20Bg(which)
    if which=="dawn" then return hg20Image("dawn",HG20_DAWN,"hg20_dawn.png") end
    if which=="route" then return hg20Image("route",HG20_ROUTE,"hg20_route.png") end
    if which=="autumn" then return hg20Image("autumn",HG20_AUTUMN,"hg20_autumn.png") end
    return hg20Image("lake",HG20_LAKE,"hg20_lake.png")
  end

  local function hg20Fit(winW,winH)
    local sc=math.min(winW/1024,winH/768)
    return sc,(winW-1024*sc)/2,(winH-768*sc)/2
  end

  local function hg20Cover(img,x,y,w,h,alpha)
    if not img then return end
    local iw,ih=img:getDimensions()
    local sc=math.max(w/iw,h/ih)
    love.graphics.setColor(1,1,1,alpha or 1)
    love.graphics.draw(img,x+(w-iw*sc)/2,y+(h-ih*sc)/2,0,sc,sc)
  end

  local function hg20FitImage(img,x,y,w,h,alpha,flip)
    if not img then return end
    local iw,ih=img:getDimensions()
    local sc=math.min(w/iw,h/ih)
    love.graphics.setColor(1,1,1,alpha or 1)
    local sx=flip and -sc or sc
    local dx=x+w/2
    local dy=y+h/2
    love.graphics.draw(img,dx,dy,0,sx,sc,iw/2,ih/2)
  end

  local function hg20Text(str,x,y,size,color,align,width)
    local g=love.graphics
    local old=g.getFont()
    local useFont=font(size)
    if useFont then g.setFont(useFont) end
    local c=color or {1,1,1,1}
    g.setColor(c[1],c[2],c[3],c[4] or 1)
    if width then g.printf(tostring(str or ""),x,y,width,align or "left")
    else g.print(tostring(str or ""),x,y) end
    if old then g.setFont(old) end
  end

  local function hg20Flash(amount)
    if amount<=0 then return end
    love.graphics.setColor(1,1,1,math.min(1,amount))
    love.graphics.rectangle("fill",0,0,1024,768)
  end

  local function hg20Petals(frame,count)
    local g=love.graphics
    for i=1,count do
      local p=((frame*0.006)+(i*0.117))%1
      local x=1080-p*1180
      local y=80+((i*73)%550)+math.sin(frame*0.035+i)*24
      local cols={{1,0.74,0.82,0.76},{1,0.94,0.58,0.76},{0.93,0.98,1,0.72}}
      local c=cols[(i%3)+1]
      g.setColor(c[1],c[2],c[3],c[4])
      g.ellipse("fill",x,y,5+(i%3),2+(i%2))
    end
  end

  local function hg20SpeedLines(frame,color)
    local g=love.graphics
    local c=color or {1,1,1,0.25}
    g.setColor(c[1],c[2],c[3],c[4] or 0.25)
    for i=1,18 do
      local x=((i*83+frame*9)%1180)-80
      local y=(i*43)%720
      g.rectangle("fill",x,y,70+(i%4)*25,2+(i%2))
    end
  end

  -- Clean copyright card.
  local ok20Copy,C20=pcall(require,"src.ui.gen2.CopyrightSplash")
  if ok20Copy and type(C20)=="table" and not C20.__hg20 then
    C20.__hg20=true
    C20.drawWidescreen=function(self,winW,winH)
      local g=love.graphics
      g.push("all"); g.origin()
      g.setColor(1,1,1,1); g.rectangle("fill",0,0,winW,winH)
      local sc,ox,oy=hg20Fit(winW,winH)
      g.push(); g.translate(ox,oy); g.scale(sc,sc)
      hg20Text("©2009 Pokémon.",0,296,20,{0.10,0.10,0.10,1},"center",1024)
      hg20Text("Nintendo / Creatures Inc. / GAME FREAK inc.",
        0,334,14,{0.30,0.30,0.30,1},"center",1024)
      g.pop(); g.pop()
    end
  end

  -- Embedded HeartGold intro music.
  -- Stored on _G rather than as a local to avoid the Lua 200-local limit.
  _G.CROSSS_HG_INTRO_AUDIO_B64=[[]]

  -- Completely original intro movie.
  local ok20Intro,I20=pcall(require,"src.ui.gen2.GoldSilverIntro")
  if ok20Intro and type(I20)=="table" and not I20.__hg20 then
    I20.__hg20=true

    -- Play the HeartGold opening music from embedded FileData instead of a
    -- relative filesystem path. The previous build silently failed because
    -- the Recomp mod loader did not resolve assets/audio/... for newSource().
    I20.__crosssOriginalFinish=I20.finish
    I20.finish=function(self,...)
      if self.__crosssIntroMusic then
        pcall(function()
          self.__crosssIntroMusic:stop()
          self.__crosssIntroMusic:release()
        end)
        self.__crosssIntroMusic=nil
      end
      return self:__crosssOriginalFinish(...)
    end

    I20.update=function(self,dt)
      if self.finished then return end

      if not self.__crosssIntroMusicStarted then
        self.__crosssIntroMusicStarted=true
        local okAudio,errAudio=pcall(function()
          local bytes=love.data.decode("string","base64",_G.CROSSS_HG_INTRO_AUDIO_B64)
          local fd=love.filesystem.newFileData(bytes,"heartgold_opening.ogg")
          -- FileData is passed directly to LÖVE, so no mod-relative path lookup
          -- is required.
          self.__crosssIntroMusic=love.audio.newSource(fd,"stream")
          self.__crosssIntroMusic:setLooping(false)
          self.__crosssIntroMusic:setVolume(0.90)
          self.__crosssIntroMusic:play()
        end)
        if not okAudio then
          print("[Heart Gold Inspired Into] HeartGold intro audio failed: "..tostring(errAudio))
        end
      end
      self.__hg20f=(self.__hg20f or 0)+1
      self.frames=(self.frames or 0)+1
      local input=self.game and self.game.input
      if input then
        for _,b in ipairs({"a","b","start","select"}) do
          if input:wasPressed(b) then
            self.skipped=true
            return self:finish()
          end
        end
      end
      if self.__hg20f>=2100 then return self:finish() end
    end

    I20.drawWidescreen=function(self,winW,winH)
      local g=love.graphics
      g.push("all"); g.origin()
      g.setColor(0,0,0,1); g.rectangle("fill",0,0,winW,winH)
      local sc,ox,oy=hg20Fit(winW,winH)
      g.push(); g.translate(ox,oy); g.scale(sc,sc)

      local f=self.__hg20f or 0

      -- SCENE 1: Celebi streaks across the darkness and reveals GAME FREAK.
      -- This replaces the abstract yellow arrow/star from the previous build.
      if f<180 then
        local q=f/180
        g.setColor(0.005,0.012,0.025,1); g.rectangle("fill",0,0,1024,768)

        -- Very subtle deep-blue night gradient so the opening is not flat black.
        for y=0,768,8 do
          local t=y/768
          g.setColor(0.008+0.010*t,0.015+0.018*t,0.035+0.045*t,1)
          g.rectangle("fill",0,y,1024,9)
        end

        -- Celebi follows the same fast sweeping trajectory as the old streak.
        local path=math.min(1,q/0.70)
        local cx=-105+path*1230
        local cy=360-math.sin(path*math.pi)*205+math.sin(path*math.pi*5)*16
        local sz=92+math.sin(path*math.pi)*26

        -- Soft green/gold trail behind Celebi.
        for i=1,12 do
          local trail=path-i*0.018
          if trail>0 then
            local tx=-105+trail*1230
            local ty=360-math.sin(trail*math.pi)*205+math.sin(trail*math.pi*5)*16
            local a=(13-i)/13*0.30
            g.setColor(0.62,1.00,0.50,a)
            g.circle("fill",tx,ty,2+i*0.55)
          end
        end

        -- Small sparkles around the flight path.
        for i=1,16 do
          local p=((q*1.45)+(i*0.091))%1
          local sx=1040-p*1120
          local sy=185+((i*73)%390)+math.sin(f*0.06+i)*17
          g.setColor(0.82,1.00,0.62,0.18+(i%4)*0.06)
          g.circle("fill",sx,sy,1+(i%3))
        end

        drawHgDexSprite(251,"front",cx-sz/2,cy-sz/2,sz,sz)

        -- Reveal the studio credit directly on the scene. No white image box.
        local textA=math.max(0,math.min(1,(f-72)/36))
        if textA>0 then
          -- faint warm glow behind the lettering, not a rectangular panel
          g.setColor(0.94,0.76,0.28,0.07*textA)
          g.ellipse("fill",512,412,250,44)

          hg20Text("GAME FREAK",0,382,27,{0.96,0.96,0.91,textA},"center",1024)
          hg20Text("PRESENTS",0,426,14,{0.66,0.73,0.66,textA},"center",1024)

          -- decorative hairlines inspired by classic Pokémon openings
          g.setColor(0.68,0.78,0.57,0.45*textA)
          g.rectangle("fill",315,416,115,1)
          g.rectangle("fill",594,416,115,1)
        end

      -- SCENE 2: source-grounded Bell Tower overworld approach.
      elseif f<440 then
        local q=(f-180)/260
        q=math.max(0,math.min(1,q))

        local tower=hg215BellBg()
        if tower then
          tower:setFilter("nearest","nearest")
          g.setColor(1,1,1,1)
          g.draw(tower,0,0)
        end

        -- Bell Tower source event: SPRITE_HOU_OBJ01 / MMODEL_HOU_OBJ01.
        local ho=hg214HoOh()
        if ho then
          ho:setFilter("nearest","nearest")
          hg20FitImage(ho,398,205,228,205,1,false)
        end

        -- Normal player source model is MMODEL_HERO; never CYCLEHERO here.
        local walk=1-((1-q)*(1-q))
        local ex=512-27
        local ey=665-walk*248
        local cycle=math.floor(f/7)%4
        local frameIndex=(cycle==0 and 1) or (cycle==1 and 2) or (cycle==2 and 3) or 2
        local hero=hg214EthanFrame(frameIndex)
        if hero then
          hero:setFilter("nearest","nearest")
          hg20FitImage(hero,ex,ey,54,78,1,false)
        end

        local logoA=math.max(0,math.min(1,(q-0.72)/0.20))
        hg20FitImage(hg20Logo(),35,32,385,180,logoA)

      -- SCENE 3: Ethan heads down Route 29 as starters flash beside him.
      elseif f<720 then
        local q=(f-440)/280
        hg21PanCover(hg21NewBark(),0,0,1024,768,q,1.28,-110,24,1)
        g.setColor(0.05,0.18,0.05,0.16); g.rectangle("fill",0,0,1024,768)
        hg20Petals(f,24)
        local bob=math.sin(f*0.11)*9
        hg20FitImage(hg20Ethan(),110+q*235,175+bob,275,440,1,false)
        local starter={152,155,158}
        local slot=math.floor((f-440)/70)%3+1
        local px=625+math.sin(f*0.045)*70
        drawHgDexSprite(starter[slot],"front",px,355+bob,180,180)
        hg20Text("NEW BARK TOWN",0,90,27,{1,1,1,0.94},"center",1024)

      -- SCENE 4: Lyra at the lake, Lapras glides through moonlight.
      elseif f<980 then
        local q=(f-720)/260
        hg21PanCover(hg24Olivine(),0,0,1024,768,q,1.08,-42,-26,1)
        g.setColor(0.03,0.08,0.18,0.10); g.rectangle("fill",0,0,1024,768)
        hg20FitImage(hg212Lyra(),650-q*90,145,285,455,1,true)
        hg20Text("OLIVINE CITY",0,625,24,{1,1,1,0.92},"center",1024)
        local lx=-190+q*1160
        local ly=415+math.sin(q*math.pi*3)*18
        drawHgDexSprite(131,"front",lx,ly,220,220)
        for i=1,18 do
          local x=(i*67+f*1.2)%1024
          local y=520+(i%5)*28
          g.setColor(0.72,0.90,1,0.30)
          g.ellipse("fill",x,y,25+(i%4)*8,3)
        end

      -- SCENE 5: Silver, using official HGSS opening/full-body assets.
      elseif f<1220 then
        local q=(f-980)/240
        g.setColor(0.035,0.006,0.018,1); g.rectangle("fill",0,0,1024,768)
        hg20SpeedLines(f,{0.84,0.08,0.14,0.24})
        for i=0,6 do
          local x=-220+i*190+q*150
          g.setColor(0.25+(i%2)*0.06,0.008,0.025,1)
          g.polygon("fill",x,0,x+110,0,x-20,768,x-130,768)
        end

        -- Official transparent opening portrait; no damaged pants/body crop.
        hg20FitImage(hg21SilverOpen(),115,125,480,360,1,false)
        -- Correct HGSS battle sprite provides the full-body silhouette.
        hg20FitImage(hg21SilverFull(),650,170,235,360,1,false)

        drawHgDexSprite(215,"front",105,480,145,145)
        drawHgDexSprite(198,"front",760,470,150,150)
        hg20Text("A RIVAL WAITS AHEAD",0,650,23,{1,0.86,0.86,0.92},"center",1024)

      -- SCENE 6: Ecruteak / Bell Tower / legendary beasts.
      elseif f<1500 then
        local q=(f-1220)/280
        if q<0.48 then
          local p=q/0.48
          hg21PanCover(hg21Ecruteak(),0,0,1024,768,p,1.18,-95,-55,1)
          g.setColor(0.55,0.18,0.05,0.09); g.rectangle("fill",0,0,1024,768)
          hg20Text("ECRUTEAK CITY",0,625,24,{1,1,1,0.90},"center",1024)
        else
          local p=(q-0.48)/0.52
          hg21PanCover(hg21Bell(),0,0,1024,768,p,3.10,-45,0,1)
          g.setColor(0.02,0.02,0.04,0.34); g.rectangle("fill",0,0,1024,768)
          local ids={243,244,245}
          for i=1,3 do
            local angle=(i-1)*2.094+p*1.5
            local cx=512+math.cos(angle)*250
            local cy=420+math.sin(angle)*82
            drawHgDexSprite(ids[i],"front",cx-95,cy-95,190,190)
          end
        end

      -- SCENE 7: Goldenrod city showcase.
      elseif f<1770 then
        local q=(f-1500)/270
        hg21PanCover(hg21Goldenrod(),0,0,1024,768,q,1.18,-145,-30,1)
        local tints={
          {0.10,0.24,0.10,0.18},{0.40,0.10,0.02,0.15},{0.04,0.18,0.36,0.15},
          {0.25,0.08,0.36,0.15},{0.38,0.28,0.04,0.15}
        }
        local pidx=math.floor((f-1500)/54)%#tints+1
        g.setColor(tints[pidx]); g.rectangle("fill",0,0,1024,768)
        hg20SpeedLines(f,{1,1,1,0.12})
        local mons={25,154,157,160,181,196,197,212,214,229}
        local idx=math.floor((f-1500)/27)%#mons+1
        local next=idx%#mons+1
        drawHgDexSprite(mons[idx],"front",140,250,295,295)
        drawHgDexSprite(mons[next],"front",590,270,245,245)
        hg20Text("GOLDENROD CITY",0,620,25,{1,1,1,0.90},"center",1024)

      -- SCENE 8: starters converge around Ethan/Lyra.
      elseif f<1950 then
        local q=(f-1770)/180
        hg21PanCover(hg21NewBark(),0,0,1024,768,q,1.18,-60,-20,1)
        hg20FitImage(hg20Ethan(),80,150,250,420,1,false)
        hg20FitImage(hg212Lyra(),695,150,250,420,1,true)
        local ids={152,155,158}
        for i=1,3 do
          local angle=(i-1)*math.pi*2/3+q*math.pi*1.2
          local cx=512+math.cos(angle)*170
          local cy=375+math.sin(angle)*80
          drawHgDexSprite(ids[i],"front",cx-95,cy-95,190,190)
        end
        hg20Petals(f,18)

      -- SCENE 9: Ho-Oh rises into the title logo.
      else
        local q=(f-1950)/150
        q=math.max(0,math.min(1,q))
        hg21PanCover(hg21Bell(),0,0,1024,768,q,3.15,-35,0,1)
        g.setColor(0.78,0.38,0.08,0.16); g.rectangle("fill",0,0,1024,768)
        local size=250+q*220
        drawHgDexSprite(250,"front",512-size/2,310-size/2,size,size)
        local a=math.max(0,math.min(1,(q-0.36)/0.45))
        hg20FitImage(hg20Logo(),170,70,684,300,a)
        if q>0.78 then
          hg20Flash((q-0.78)/0.22)
        end
      end

      if f>180 then hg20Text("A / START  SKIP",842,731,11,{1,1,1,0.70}) end
      g.pop(); g.pop()
    end
  end

  -- HeartGold title screen: clean sunrise, source logo, animated Ho-Oh entry.
  local ok20Title,T20=pcall(require,"src.ui.gen2.TitleState")
  if ok20Title and type(T20)=="table" and not T20.__hg29 then
    T20.__hg20=true
    T20.__hg22=true
    T20.__hg25=true
    T20.__hg27=true
    T20.__hg28=true
    T20.__hg29=true
    T20.drawWidescreen=function(self,winW,winH)
      local g=love.graphics
      g.push("all"); g.origin()
      g.setColor(0,0,0,1); g.rectangle("fill",0,0,winW,winH)

      local sky=hg29SkyClean()
      if sky then
        local iw,ih=sky:getDimensions()
        local bsc=math.max(winW/iw,winH/ih)
        local dw,dh=iw*bsc,ih*bsc
        g.setColor(1,1,1,1)
        g.draw(sky,(winW-dw)/2,(winH-dh)/2,0,bsc,bsc)
      end

      local sc=math.min(winW/1024,winH/768)
      local ox=(winW-1024*sc)/2
      local oy=(winH-768*sc)/2
      g.push(); g.translate(ox,oy); g.scale(sc,sc)

      self.__hg29TitleFrames=(self.__hg29TitleFrames or 0)+1
      local f=self.__hg29TitleFrames
      local enter=hg29EaseOutCubic(math.min(1,f/72))

      -- HeartGold logo from the supplied source files.
      hg20FitImage(hg20Logo(),224,58,575,270,1)

      -- Ho-Oh starts completely offscreen on the left and sweeps beneath the
      -- logo before settling into its idle bob.
      local targetX=354
      local startX=-430
      local hoX=startX+(targetX-startX)*enter
      local arc=math.sin(math.min(1,f/72)*math.pi)*72
      local bob=(enter>=1) and math.sin(f*0.045)*8 or 0
      drawHgDexSprite(250,"front",hoX,385-arc+bob,315,315)

      if math.floor(f/30)%2==0 then
        hg20Text("PRESS START",0,705,26,{1,1,1,0.98},"center",1024)
      end
      hg20Text("©2009 Pokémon. Nintendo / Creatures Inc. / GAME FREAK inc.",
        0,716,11,{1,1,1,0.72},"center",1024)

      g.pop()
      g.pop()
    end
  end

  local ok20Main,M20=pcall(require,"src.ui.gen2.MainMenu")
  if ok20Main and type(M20)=="table" and not M20.__hg29 then
    M20.__hg20=true
    M20.__hg22=true
    M20.__hg25=true
    M20.__hg27=true
    M20.__hg28=true
    M20.__hg29=true
    M20.drawWidescreen=function(self,winW,winH)
      local g=love.graphics
      g.push("all"); g.origin()
      g.setColor(0,0,0,1); g.rectangle("fill",0,0,winW,winH)

      local sky=hg29SkyClean()
      if sky then
        local iw,ih=sky:getDimensions()
        local bsc=math.max(winW/iw,winH/ih)
        local dw,dh=iw*bsc,ih*bsc
        g.setColor(1,1,1,1)
        g.draw(sky,(winW-dw)/2,(winH-dh)/2,0,bsc,bsc)
      end

      local sc=math.min(winW/1024,winH/768)
      local ox=(winW-1024*sc)/2
      local oy=(winH-768*sc)/2
      g.push(); g.translate(ox,oy); g.scale(sc,sc)

      self.__hg29MenuFrames=(self.__hg29MenuFrames or 0)+1
      local f=self.__hg29MenuFrames
      local enter=hg29EaseOutCubic(math.min(1,f/48))

      -- Source-file HeartGold logo stays in place.
      hg20FitImage(hg20Logo(),142,52,500,230,1)

      -- Ho-Oh flies in independently from the left.
      local targetHoX=60
      local hoX=-390+(targetHoX+390)*enter
      local hoArc=math.sin(math.min(1,f/48)*math.pi)*55
      local bob=(enter>=1) and math.sin(f*0.045)*7 or 0
      drawHgDexSprite(250,"front",hoX,350-hoArc+bob,280,280)

      -- Entire menu/continue card slides in from the right.
      local targetMenuX=(self.phase=="confirm") and 600 or 610
      local menuX=1120+(targetMenuX-1120)*enter

      if self.phase~="confirm" then
        local items=self.list and self.list.items or {}
        local selected=self.list and self.list.index or 1

        local boxX,boxY,boxW=menuX,350,320
        local rowH=57
        local boxH=math.max(120,#items*rowH+26)

        g.setColor(0.99,0.97,0.88,0.96)
        g.rectangle("fill",boxX,boxY,boxW,boxH)
        g.setColor(0.35,0.22,0.08,1)
        g.setLineWidth(4)
        g.rectangle("line",boxX,boxY,boxW,boxH)
        g.setColor(0.74,0.54,0.26,1)
        g.setLineWidth(2)
        g.rectangle("line",boxX+7,boxY+7,boxW-14,boxH-14)

        local y=boxY+17
        for i,item in ipairs(items) do
          local sel=i==selected
          if sel then
            g.setColor(0.67,0.37,0.07,1)
            g.polygon("fill",boxX+24,y+12,boxX+24,y+34,boxX+41,y+23)
          end
          hg20Text(tostring(item.label or item.value or ""):upper(),
            boxX+60,y+9,18,sel and {0.35,0.20,0.04,1} or {0.16,0.16,0.14,1})
          y=y+rowH
        end
      else
        local boxX,boxY,boxW,boxH=menuX,330,335,270
        g.setColor(0.99,0.97,0.88,0.97)
        g.rectangle("fill",boxX,boxY,boxW,boxH)
        g.setColor(0.35,0.22,0.08,1)
        g.setLineWidth(4)
        g.rectangle("line",boxX,boxY,boxW,boxH)
        g.setColor(0.74,0.54,0.26,1)
        g.setLineWidth(2)
        g.rectangle("line",boxX+7,boxY+7,boxW-14,boxH-14)

        local summary=nil
        local okSave,Save=pcall(require,"src.core.gen2.Save")
        if okSave and Save and Save.summary then
          local ok,res=pcall(Save.summary,self.save)
          if ok then summary=res end
        end
        summary=summary or {}
        hg20Text("CONTINUE",boxX+28,boxY+26,20,{0.35,0.20,0.04,1})
        hg20Text("PLAYER  "..tostring(summary.name or "GOLD"),boxX+28,boxY+78,15,{0.15,0.14,0.12,1})
        hg20Text("BADGES  "..tostring(summary.badges or 0),boxX+28,boxY+118,15,{0.15,0.14,0.12,1})
        hg20Text("POKéDEX  "..tostring(summary.caught or 0),boxX+28,boxY+158,15,{0.15,0.14,0.12,1})
        hg20Text(string.format("TIME  %d:%02d",summary.hours or 0,summary.minutes or 0),
          boxX+28,boxY+198,15,{0.15,0.14,0.12,1})
        hg20Text("A CONTINUE   B BACK",boxX+28,boxY+238,11,{0.36,0.32,0.25,1})
      end

      g.pop()
      g.pop()
    end
  end


  introLog("info","Heart Gold Inspired Into v1.0.0 loaded — standalone intro/title only")
end
